contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public payable {
        require(true);
        // Unfreeze sender and recipient so the transfer can succeed if balances permit.
        c.freezeAccount(address(this), false); if (__ESBMC_reverted()) return;
        c.freezeAccount(to, false); if (__ESBMC_reverted()) return;

        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;

        require(to != address(0));
        require(to != address(this));
        require(senderBefore >= amount);

        bool success = c.transfer(to, amount); if (__ESBMC_reverted()) return;

        uint256 recipientAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(success == true && recipientAfter == recipientBefore + amount);
    }

    receive() external payable {}
}

