        try c.freezeAccount(address(this), false) {} catch { return; }
        try c.freezeAccount(to, false) {} catch { return; }
        uint256 senderBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { senderBefore = __r; } catch { return; }
        uint256 recipientBefore;
        try c.balanceOf(to) returns (uint256 __r) { recipientBefore = __r; } catch { return; }
        vm.assume(to != address(0));
        vm.assume(to != address(this));
